/* String instructions for lifted code (M5). Generated by lift/ops_string.py.
 *
 * Every helper takes size 1, 2 or 4 (the element width in bytes). Call sites pass a constant, so
 * the size switches fold away after inlining.
 *
 * Semantics follow the Intel SDM, element by element:
 *   - the direction comes from c->df: ESI/EDI step by +size, or by -size when DF=1;
 *   - ECX counts down, and a rep loop ends when ECX reaches 0;
 *   - repe/repne also end after an element whose ZF is 0 (repe) or 1 (repne);
 *   - cmps and scas set the six arithmetic flags of their last comparison; with no element run the
 *     flags are unchanged;
 *   - ESI and EDI end advanced by the number of elements done.
 *
 * Only rep movs and rep stos (DF=0) take a bulk path. Those paths produce the same bytes as the
 * element loop: memmove is used when the forward element copy cannot read a byte it already wrote
 * (dst <= src, or dst - src >= the byte count), and memset for byte stores. Any other overlap
 * (dst just above src) runs the element loop, which replicates the pattern as the hardware does. */
#ifndef LIFT_STROPS_H
#define LIFT_STROPS_H

#include "cpu.h"
#include "flags.h"

static inline uint32_t str_step(const CPU *c, uint32_t size)
{
    return c->df ? (uint32_t)0 - size : size;
}

static inline uint32_t str_ld(CPU *c, uint32_t a, uint32_t size)
{
    return size == 1 ? rd8(c, a) : size == 2 ? rd16(c, a) : rd32(c, a);
}

static inline void str_st(CPU *c, uint32_t a, uint32_t size, uint32_t v)
{
    if (size == 1)
        wr8(c, a, (uint8_t)v);
    else if (size == 2)
        wr16(c, a, (uint16_t)v);
    else
        wr32(c, a, v);
}

static inline uint32_t str_acc(const CPU *c, uint32_t size)
{
    return size == 1 ? (c->r[EAX] & 0xffu) : size == 2 ? (c->r[EAX] & 0xffffu) : c->r[EAX];
}

/* Writes the low `size` bytes of EAX and keeps the rest (AL and AX leave the upper bits alone). */
static inline void str_set_acc(CPU *c, uint32_t size, uint32_t v)
{
    if (size == 1)
        c->r[EAX] = (c->r[EAX] & 0xffffff00u) | (v & 0xffu);
    else if (size == 2)
        c->r[EAX] = (c->r[EAX] & 0xffff0000u) | (v & 0xffffu);
    else
        c->r[EAX] = v;
}

/* Flags of a - b at the given width. */
static inline void str_cmp(CPU *c, uint32_t size, uint32_t a, uint32_t b)
{
    if (size == 1)
        flags_sub8(c, a, b);
    else if (size == 2)
        flags_sub16(c, a, b);
    else
        flags_sub32(c, a, b);
}

/* ---- one element (no prefix) ---- */

static inline void str_movs(CPU *c, uint32_t size)              /* [edi] = [esi] */
{
    str_st(c, c->r[EDI], size, str_ld(c, c->r[ESI], size));
    c->r[ESI] += str_step(c, size);
    c->r[EDI] += str_step(c, size);
}

static inline void str_stos(CPU *c, uint32_t size)              /* [edi] = acc */
{
    str_st(c, c->r[EDI], size, str_acc(c, size));
    c->r[EDI] += str_step(c, size);
}

static inline void str_lods(CPU *c, uint32_t size)              /* acc = [esi] */
{
    str_set_acc(c, size, str_ld(c, c->r[ESI], size));
    c->r[ESI] += str_step(c, size);
}

static inline void str_scas(CPU *c, uint32_t size)              /* flags of acc - [edi] */
{
    str_cmp(c, size, str_acc(c, size), str_ld(c, c->r[EDI], size));
    c->r[EDI] += str_step(c, size);
}

static inline void str_cmps(CPU *c, uint32_t size)              /* flags of [esi] - [edi] */
{
    str_cmp(c, size, str_ld(c, c->r[ESI], size), str_ld(c, c->r[EDI], size));
    c->r[ESI] += str_step(c, size);
    c->r[EDI] += str_step(c, size);
}

/* ---- rep movs / rep stos / rep lods ---- */

static inline void str_rep_movs(CPU *c, uint32_t size)
{
    uint32_t n = c->r[ECX];
    if (n == 0)
        return;
    if (!c->df) {
        uint32_t src = c->r[ESI], dst = c->r[EDI];
        uint64_t bytes = (uint64_t)n * size;
        if (dst <= src || (uint64_t)(uint32_t)(dst - src) >= bytes) {
            NOTE_WRITE(c, dst, bytes);
            memmove(MEM(c, dst), MEM(c, src), (size_t)bytes);
            c->r[ESI] = src + (uint32_t)bytes;
            c->r[EDI] = dst + (uint32_t)bytes;
            c->r[ECX] = 0;
            return;
        }
    }
    while (c->r[ECX] != 0) {
        str_movs(c, size);
        c->r[ECX]--;
    }
}

static inline void str_rep_stos(CPU *c, uint32_t size)
{
    if (!c->df && size == 1) {
        uint32_t n = c->r[ECX];
        if (n != 0) {
            NOTE_WRITE(c, c->r[EDI], n);
            memset(MEM(c, c->r[EDI]), (int)(c->r[EAX] & 0xffu), n);
        }
        c->r[EDI] += n;
        c->r[ECX] = 0;
        return;
    }
    while (c->r[ECX] != 0) {
        str_stos(c, size);
        c->r[ECX]--;
    }
}

static inline void str_rep_lods(CPU *c, uint32_t size)
{
    while (c->r[ECX] != 0) {
        str_lods(c, size);
        c->r[ECX]--;
    }
}

/* ---- repe / repne: scas and cmps ---- */

static inline void str_repe_scas(CPU *c, uint32_t size)
{
    while (c->r[ECX] != 0) {
        str_scas(c, size);
        c->r[ECX]--;
        if (!c->zf)
            break;
    }
}

static inline void str_repne_scas(CPU *c, uint32_t size)
{
    while (c->r[ECX] != 0) {
        str_scas(c, size);
        c->r[ECX]--;
        if (c->zf)
            break;
    }
}

static inline void str_repe_cmps(CPU *c, uint32_t size)
{
    while (c->r[ECX] != 0) {
        str_cmps(c, size);
        c->r[ECX]--;
        if (!c->zf)
            break;
    }
}

static inline void str_repne_cmps(CPU *c, uint32_t size)
{
    while (c->r[ECX] != 0) {
        str_cmps(c, size);
        c->r[ECX]--;
        if (c->zf)
            break;
    }
}

#endif
